type Bus struct {
	log Logger

	mu      sync.RWMutex
	subs    map[chan Event]struct{}
	closed  bool
}

// NewBus constructs a Bus rooted at home. home is unused in this task
// (used in Task 4 for the JSONL writer).
func NewBus(home string, log Logger) (*Bus, error) {
	return &Bus{
		log:  log,
		subs: map[chan Event]struct{}{},
	}, nil
}

// DaemonLogPath returns the path for a daily-rotated log file.
// dateYYYYMMDD must be formatted as "20260428".
func DaemonLogPath(homeDir, dateYYYYMMDD string) string {
	return filepath.Join(DaemonLogsDir(homeDir), "daemon-"+dateYYYYMMDD+".log")
}

// Close stops new publishes and closes all subscriber channels.
func (b *Bus) Close() error {
	b.mu.Lock()
	defer b.mu.Unlock()
	b.closed = true
	for ch := range b.subs {
		close(ch)
	}
	b.subs = nil
	return nil
}

