func SlugForPath(p string) string {
	if p == "" || p == "/" {
		return "root"
	}
	s := strings.TrimPrefix(p, "/")
	s = strings.ReplaceAll(s, "/", "-")
	s = strings.ToLower(s)
	s = nonAlnum.ReplaceAllString(s, "-")
	s = strings.Trim(s, "-")
	if s == "" {
		return "root"
	}
	return s
}

